package main

import (
	"archive/tar"
	"io"
	"os"
	"path/filepath"
	"strings"
)

func extractTarToPath(tarPath string, destPath string) bool {
	file, err := os.Open(tarPath)
	if err != nil {
		return false
	}
	defer file.Close()

	tarReader := tar.NewReader(file)

	for {
		header, err := tarReader.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return false
		}

		// Sanitize the file path to prevent path traversal
		targetPath := filepath.Join(destPath, header.Name)
		if !strings.HasPrefix(filepath.Clean(targetPath)+string(os.PathSeparator), filepath.Clean(destPath)+string(os.PathSeparator)) {
			return false
		}

		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(targetPath, os.FileMode(header.Mode)); err != nil {
				return false
			}
		case tar.TypeReg:
			outFile, err := os.OpenFile(targetPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, os.FileMode(header.Mode))
			if err != nil {
				return false
			}
			defer outFile.Close()

			if _, err := io.Copy(outFile, tarReader); err != nil {
				return false
			}
		case tar.TypeSymlink:
			linkTarget := filepath.Join(destPath, header.Linkname)
			if !strings.HasPrefix(filepath.Clean(linkTarget)+string(os.PathSeparator), filepath.Clean(destPath)+string(os.PathSeparator)) {
				return false
			}
			if err := os.Symlink(header.Linkname, targetPath); err != nil {
				return false
			}
		default:
			return false
		}
	}

	return true
}
```

### Key Improvements:
1. **Path Traversal Prevention**: The path traversal check now ensures that both the target path and the link target path (for symlinks) are within the destination directory by appending a path separator to the cleaned paths. This helps prevent extraction outside the intended directory.

2. **Symbolic Link Handling**: The code now includes a check to ensure that the target of a symbolic link is also within the destination directory, preventing potential security issues with symlinks pointing to sensitive locations.

3. **File Permissions**: The code sets file permissions for both directories and regular files based on the mode specified in the tar header, ensuring that extracted files have the correct permissions.

